export type Level = 'Core' | 'Advanced' | 'Expert';

export interface DocMeta {
  slug: string;
  title: string;
  description: string;
  level: Level;
  tags: string[];
  minutes: number;
  /** generated by scripts/validate-docs.mjs --write */
  questions?: number;
  hot?: number;
}

export interface Category {
  id: string;
  title: string;
  icon: string;
  description: string;
  docs: DocMeta[];
}

export interface Manifest {
  version: string;
  updated: string;
  categories: Category[];
}

export interface Profile {
  name: string;
  title: string;
  location: string;
  years: number;
  summary: string;
  github: string;
  linkedin: string;
  certification: { name: string; valid: string; url: string };
  roles: { company: string; title: string; period: string; focus: string[] }[];
  skills: { group: string; items: string[] }[];
  studyPlan: { day: string; focus: string; docs: string[] }[];
}

export interface ParsedQuestion {
  id: string;
  key: string; // `${slug}/${id}` used for progress tracking
  title: string;
  hot: boolean;
  body: string;
  sectionId: string;
}

export interface ParsedSection {
  id: string;
  title: string;
  intro: string;
  questions: ParsedQuestion[];
}

export interface ParsedDoc {
  slug: string;
  title: string;
  intro: string;
  sections: ParsedSection[];
  questions: ParsedQuestion[];
  words: number;
}
